import React, { useState, useEffect } from 'react';
import './App.css';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import { useAuth } from './hooks/useAuth';

function App() {
  const { user, login, logout, isAuthenticated } = useAuth();
  const [showDashboard, setShowDashboard] = useState(false);
  const [loginError, setLoginError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (isAuthenticated) setShowDashboard(true);
  }, [isAuthenticated]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    setIsLoading(true);
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const credentials = {
      username: formData.get('username') as string,
      password: formData.get('password') as string,
    };
    const success = await login(credentials);
    setIsLoading(false);
    if (success) {
      setShowDashboard(true);
    } else {
      setLoginError('Invalid credentials. Please try again.');
    }
  };

  const handleLogout = () => {
    logout();
    setShowDashboard(false);
  };

  if (!isAuthenticated) {
    return (
      <div className="login-page">
        <div className="login-container">
          <div className="login-brand">
            <div className="login-logo" aria-hidden="true">🚗</div>
            <h1>Mr. Rideo</h1>
            <p>Admin Dashboard — Sign in to continue</p>
          </div>

          {loginError && (
            <div className="login-error" role="alert">
              <span aria-hidden="true">⚠️</span>
              {loginError}
            </div>
          )}

          <form className="login-form" onSubmit={handleLogin} noValidate>
            <div className="form-group">
              <label className="form-label" htmlFor="username">Username</label>
              <input
                id="username"
                className="form-input"
                type="text"
                name="username"
                placeholder="Enter your username"
                autoComplete="username"
                required
                disabled={isLoading}
              />
            </div>
            <div className="form-group">
              <label className="form-label" htmlFor="password">Password</label>
              <input
                id="password"
                className="form-input"
                type="password"
                name="password"
                placeholder="Enter your password"
                autoComplete="current-password"
                required
                disabled={isLoading}
              />
            </div>
            <button
              id="login-btn"
              className="btn-primary"
              type="submit"
              disabled={isLoading}
            >
              {isLoading && <span className="login-spinner" aria-hidden="true" />}
              {isLoading ? 'Signing in…' : 'Sign in'}
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="App">
      <Sidebar user={user} onLogout={handleLogout} />
      <main className="main-content">
        {showDashboard ? (
          <Dashboard />
        ) : (
          <div className="welcome-screen">
            <span className="welcome-icon" aria-hidden="true">🚗</span>
            <h2 className="welcome-title">Welcome back{user?.name ? `, ${user.name}` : ''}!</h2>
            <p className="welcome-subtitle">
              Select a section from the sidebar to get started managing your platform.
            </p>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
